# Independent composite Simpson on each frame's partition, built from exact dyadic panels
# generated by replaying the split sequence (not from the script's node lists), using mpmath per-panel.
import mpmath
mpmath.mp.dps=30
f=lambda x: 1+mpmath.exp(-x)*mpmath.sin(8*mpmath.cbrt(x)**2)
S=lambda a,b:(b-a)/6*(f(a)+4*f((a+b)/2)+f(b))
F=mpmath.mpf
splits=[(0,2),(0,1),(1,2),(0.5,1),(0,0.5),(1,1.5),(0,0.25),(0.25,0.5),(0.5,0.75),(0.75,1),(0,0.125),(0.125,0.25)]+[(0,2.0**-k) for k in range(4,11)]
P={(F(0),F(2))}
print(" set  points  composite")
print(f"  1 {3:6d}  {mpmath.nstr(sum(S(a,b) for a,b in P),10)}")
for i,(a,b) in enumerate(splits[:-0 or None]):
    a,b=F(a),F(b)
    if (a,b) not in P: break
    P.remove((a,b)); m=(a+b)/2; P|={(a,m),(m,b)}
    print(f" {i+2:2d} {2*len(P)+1:6d}  {mpmath.nstr(sum(S(a,b) for a,b in P),10)}")
